            map<bitset<128>, FieldMod> G;
            G[1] = 1;
            for (int i = 0; i < N; ++i) {
                map<vector<int>, FieldMod> H;
                for (auto g: G) {
                    vector<int> S;
                    for (int m = 0; m < (1 << N); ++m) if (g.x[m]) S.push_back(m);
