                        for (int l = 0; l < N; ++l) {
                            if ((j & (1 << l)) == 0) continue;
                            for (int m: h.x) if ((m & (1 << l)) == 0) ans[m | (1 << l)] = true;
                        }
                        if (ans.any()) G[ans] += h.y * pst;
                    }
                }
